mapper.select:
SELECT e.id, e.user_id, e.category_id, e.name, e.url, e.username, e.password, e.created_at, e.updated_at, c.name AS category_name FROM password_entry e LEFT JOIN password_category c ON e.category_id = c.id WHERE e.user_id = #{userId}
AND (e.name LIKE CONCAT('%', #{searchKey}, '%') OR e.url LIKE CONCAT('%', #{searchKey}, '%') OR e.username LIKE CONCAT('%', #{searchKey}, '%'))
AND e.category_id = #{categoryId}
ORDER BY e.updated_at DESC

mapper.update:
UPDATE password_entry
category_id = #{categoryId}, name = #{name}, url = #{url}, username = #{username}, password = #{password},
WHERE id = #{id}
